SELECT ?entity ?cls ?label ?point ?pointcls ?tsid WHERE {
  ?entity a brick:AirHandlingUnit .
  FILTER(str(?entity) LIKE "%AHU02%")
  OPTIONAL { ?point brick:hasPropertyParameter ?entity }
  OPTIONAL {
    ?point ref:hasTimeseriesId ?tsid .
    ?point a ?pointcls .
  }
}

SELECT ?entity ?point ?pointcls ?tsid WHERE {
  ?entity a brick:AirHandlingUnit .
  FILTER(str(?entity) LIKE "%AHU02%")
  ?point ref:hasTimeseriesId ?tsid .
  ?point a ?pointcls .
}

SELECT ?s ?label ?cls WHERE {
  ?s rdfs:label ?label .
  ?s a ?cls .
  FILTER(str(?label) LIKE "%AHU%")
}

